// ===== Estadísticas por obra =====
let statsRange='month';
const ymd=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
function statsBounds(){const t=today(),d=new Date(t+'T12:00:00'),y=d.getFullYear();if(statsRange==='q'){const ds=Core.dates(t.slice(0,7),+t.slice(8)<=15?'1':'2');return [ds[0],ds[ds.length-1],'Esta quincena']}if(statsRange==='month')return [t.slice(0,7)+'-01',t,'Este mes'];if(statsRange==='3m'){const a=new Date(d);a.setMonth(a.getMonth()-3);return [ymd(a),t,'Últimos 3 meses']}if(statsRange==='year')return [y+'-01-01',t,'Este año '+y];return ['1900-01-01','2200-12-31','Todo el historial']}
function statsView(){const [a,b,label]=statsBounds(),{list,tot}=Core.placeStats(state,a,b),max=Math.max(1,...list.map(e=>e.days)),most=list[0],ext=[...list].sort((x,y)=>y.extra-x.extra)[0],long=[...list].sort((x,y)=>y.avgHours-x.avgHours)[0];
 return '<button class="link back" data-go="summary">'+icon('left')+' Quincena</button><p class="lead">Misma empresa, distintas obras: dónde estuviste, cuántas horas y cuántas extras hiciste en cada una.</p><div class="chips toc">'+[['q','Quincena'],['month','Mes'],['3m','3 meses'],['year','Año'],['all','Todo']].map(([k,t])=>'<button type="button" class="chip" data-stats-range="'+k+'" aria-pressed="'+(statsRange===k)+'">'+t+'</button>').join('')+'</div>'
 +(!list.length?'<div class="empty">'+icon('hours')+'<p>No hay días trabajados en '+esc(label.toLowerCase())+'.</p></div>':'<section class="hero stats-hero"><div class="hero-label"><span>'+esc(label)+'</span><span class="pill">'+list.length+(list.length===1?' obra':' obras')+'</span></div><div class="grid"><div class="metric"><small>Días</small><b>'+tot.days+'</b></div><div class="metric"><small>Horas</small><b>'+compactHours(tot.hours)+'</b></div><div class="metric"><small>Extras</small><b>'+compactHours(tot.extra)+'</b></div></div>'+(state.rules.length?'<div class="line"><span>Generado en días trabajados</span><strong>'+money(tot.total)+'</strong></div>':'')+'</section>'
 +'<div class="insights">'+[most&&['Donde más fuiste',most.place,most.days+(most.days===1?' día':' días')],ext&&ext.extra>0&&['Donde más extras hiciste',ext.place,compactHours(ext.extra)],long&&list.length>1&&['Jornadas más largas',long.place,compactHours(long.avgHours)+' por día']].filter(Boolean).map(([t,p,v])=>'<div class="insight"><small>'+t+'</small><b>'+esc(p)+'</b><span>'+v+'</span></div>').join('')+'</div>'
 +'<section class="panel"><h2>Por obra</h2>'+list.map(e=>'<button type="button" class="place-row" data-stats-place="'+esc(e.place)+'"><span class="pr-top"><b>'+esc(e.place)+'</b><span>'+e.days+(e.days===1?' día':' días')+'</span></span><span class="bar"><i style="width:'+Math.round(e.days/max*100)+'%"></i></span><small>'+compactHours(e.hours)+' · '+(e.extra?compactHours(e.extra)+' extra · ':'')+compactHours(e.avgHours)+' por día'+(e.special?' · '+e.special+' especiales':'')+(state.rules.length?' · '+money(e.total):'')+'</small><small>'+(e.first===e.last?dateLabel(e.first):dateLabel(e.first)+' → '+dateLabel(e.last))+' · '+Math.round(e.share*100)+' % de tus días</small></button>').join('')+'</section><p class="muted">Tocá una obra para ver todos sus días.</p>')}
function statsCard(){if(!state.settings.placeStats)return '';const ds=Core.dates(month(),part()),{list}=Core.placeStats(state,ds[0],ds[ds.length-1]);if(!list.length)return '';return '<section class="panel"><div class="panel-head"><h2>Por obra</h2><button class="link" data-go="stats">Ver más '+icon('arrow')+'</button></div>'+list.slice(0,4).map(e=>'<div class="line"><span>'+esc(e.place)+'</span><strong>'+e.days+(e.days===1?' día':' días')+' · '+compactHours(e.hours)+'</strong></div>').join('')+'</section>'}

// ===== Funciones opcionales =====
function featureToggle(b){const k=b.dataset.feature,on=b.checked;if(k==='checks'||k==='placeStats')return mutate(()=>state.settings[k]=on,on?'Activado.':'Desactivado.');if(k==='specialPay'){if(on&&!confirm('Cuando cargues un domingo, sábado o feriado, la app te va a PREGUNTAR si lo pagan distinto. Nunca lo aplica sola. ¿Activar?')){b.checked=false;return}return mutate(()=>state.settings.specialPay.enabled=on,on?'Pago especial: te vamos a preguntar.':'Pago especial desactivado.')}if(k==='payday'){if(on&&!confirm('Vas a ver un aviso en Quincena cuando llegue el día de cobro'+(window.Android?' y una notificación del teléfono':'')+'. ¿Activar?')){b.checked=false;return}if(mutate(()=>state.settings.payday.enabled=on,on?'Aviso de cobro activado.':'Aviso de cobro desactivado.'))syncNative()}if(k==='secure'){prefsSet('secure',on?'1':'');syncNative();toast(on?'La app se oculta en recientes y no permite capturas.':'Ocultar en recientes desactivado.')}if(k==='lock'){if(on)pinSetup(b);else{b.checked=true;pinVerify('Quitar bloqueo',()=>{prefsSet('pin','');prefsSet('bio','');prefsSet('pin-fails','0');prefsSet('pin-until','0');toast('Bloqueo desactivado.');render()})}}if(k==='bio'){if(on){b.checked=false;if(!bioReady())return toast('Este teléfono no tiene huella configurada.');bioEnroll=ok=>{if(ok){prefsSet('bio','1');toast('Desbloqueo con huella activado.')}else toast('No se activó la huella.');render()};Android.bioAuth()}else{prefsSet('bio','');toast('Huella desactivada. Se va a pedir el PIN.')}}}
