 const f=$('pdForm'),val=()=>{const d=new FormData(f);return {...state.settings.payday,first:Number(d.get('first')),second:Number(d.get('second')),firstMonth:d.get('firstMonth'),secondMonth:d.get('secondMonth'),notify:d.has('notify'),hour:Number(d.get('hour'))}},pv=()=>{const v=val();$('pdPv').innerHTML='<span>Próximos cobros</span>'+Core.paydays(v,today(),4).map(x=>'<div class="line"><span>'+esc(qLong(x.key))+'</span><b>'+dateLabel(x.date)+'</b></div>').join('')};f.oninput=pv;f.onchange=pv;pv();
