function syncNative(){if(!window.Android)return;try{if(Android.setSecure)Android.setSecure(prefsGet('secure')==='1');if(Android.setPayday){const pd=state.settings.payday,on=pd.enabled&&pd.notify,dates={};if(on)for(const x of Core.paydays(pd,today(),8))dates[x.date]='Hoy deberían pagarte la '+qLong(x.key)+'. Registrá el cobro en Mi Quincena.';{const j=JSON.stringify({enabled:on,hour:pd.hour,dates});if(prefsGet('payday-sent')!==j){Android.setPayday(j);prefsSet('payday-sent',j)}}}}catch(e){}}
// ===== Bloqueo con PIN (el PIN nunca se guarda: solo su huella SHA-256 con sal, y no viaja en las copias) =====
async function pinHash(pin,salt){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+':'+pin));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function pinSetup(sw){if(!window.crypto?.subtle){sw.checked=false;return toast('Este teléfono no permite el bloqueo con PIN.')}sw.checked=false;modal('<h2>Crear PIN</h2><p class="muted">Se pide al abrir la app y al volver después de 1 minuto. Si te equivocás 5 veces, hay que esperar (30 s, 1 min, 2 min…). Si lo olvidás, hay que borrar los datos de la app: tené una copia de seguridad.</p><form id="pinForm"><label>PIN (4 a 8 números)<input name="a" type="password" inputmode="numeric" pattern="[0-9]{4,8}" minlength="4" maxlength="8" required autocomplete="off"></label><label>Repetí el PIN<input name="b" type="password" inputmode="numeric" pattern="[0-9]{4,8}" minlength="4" maxlength="8" required autocomplete="off"></label>'+formEnd('Activar bloqueo')+'</form>');$('pinForm').onsubmit=async e=>{e.preventDefault();const f=e.target.elements;if(!/^\d{4,8}$/.test(f.a.value))return formError('Usá de 4 a 8 números.');if(f.a.value!==f.b.value)return formError('Los PIN no coinciden.');const salt=uid();prefsSet('pin',salt+'$'+await pinHash(f.a.value,salt));prefsSet('pin-fails','0');prefsSet('pin-until','0');closeModal();toast(bioReady()?'PIN activado. Podés sumar la huella en Funciones.':'Bloqueo con PIN activado.');render()}}
const bioReady=()=>{try{return !!(window.Android&&Android.bioAvailable&&Android.bioAvailable())}catch(e){return false}};
// Intentos: cada 5 errores hay que esperar 30 s, 1 min, 2 min… (máx. 15 min). Se guarda para que reiniciar la app no lo saltee.
function pinWait(){return Math.max(0,Number(prefsGet('pin-until')||0)-Date.now())}
async function pinCheck(v){const w=pinWait();if(w)return {ok:false,wait:w};const [salt,h]=prefsGet('pin').split('$');if(await pinHash(v,salt)===h){prefsSet('pin-fails','0');prefsSet('pin-until','0');return {ok:true}}const f=Number(prefsGet('pin-fails')||0)+1;prefsSet('pin-fails',String(f));if(f%5===0){const ms=Math.min(15*60000,30000*2**(f/5-1));prefsSet('pin-until',String(Date.now()+ms));return {ok:false,wait:ms}}return {ok:false,left:5-f%5}}
const mmss=ms=>{const t=Math.ceil(ms/1000);return Math.floor(t/60)+':'+String(t%60).padStart(2,'0')};
// Formulario de PIN reutilizable (pantalla de bloqueo y confirmaciones). box: contenedor; done: al acertar.
function pinUI(box,done,{bio=false}={}){box.innerHTML='<input class="pin-in" type="password" inputmode="numeric" maxlength="8" autocomplete="off" aria-label="PIN"><p class="error pin-err" role="alert"></p><p class="pin-timer" hidden></p><button class="primary pin-go">Desbloquear</button>'+(bio?'<button class="pin-bio">'+icon('lock')+' Usar huella</button>':'');const inp=box.querySelector('.pin-in'),err=box.querySelector('.pin-err'),tm=box.querySelector('.pin-timer'),go=box.querySelector('.pin-go');let iv;
 const tick=()=>{const w=pinWait();inp.disabled=go.disabled=w>0;tm.hidden=!w;if(w){tm.textContent='Demasiados intentos. Probá de nuevo en '+mmss(w);err.textContent=''}else{clearInterval(iv);iv=null;tm.hidden=true;if(document.activeElement!==inp)inp.focus()}};
 const startTimer=()=>{if(!iv)iv=setInterval(tick,250);tick()};
 const run=async()=>{if(!inp.value)return;const r=await pinCheck(inp.value);inp.value='';if(r.ok){clearInterval(iv);done();return}if(r.wait)startTimer();else err.textContent='PIN incorrecto. '+(r.left===1?'Queda 1 intento':'Quedan '+r.left+' intentos')+' antes de tener que esperar.'};
 go.onclick=run;inp.onkeydown=e=>{if(e.key==='Enter')run()};if(box.querySelector('.pin-bio'))box.querySelector('.pin-bio').onclick=()=>{try{Android.bioAuth()}catch(e){}};if(pinWait())startTimer();else setTimeout(()=>inp.focus(),120);return {focus:()=>{if(!pinWait())inp.focus()},msg:t=>err.textContent=t}}
let hiddenAt=0,locked=false,lockUI=null,bioEnroll=null;
window.onBio=(r,code)=>{if(bioEnroll){const cb=bioEnroll;bioEnroll=null;cb(r==='ok');return}if(!locked||!lockUI)return;if(r==='ok'){unlock();return}if(r==='err'&&(code===7||code===9))lockUI.msg('Demasiados intentos con huella. Usá tu PIN.');else if(r==='err'&&code===11)lockUI.msg('No hay huellas registradas en el teléfono. Usá tu PIN.');lockUI.focus()};
function unlock(){locked=false;lockUI=null;const d=$('lock');if(d)d.remove()}
function lockScreen(){if(locked||!prefsGet('pin'))return;locked=true;if($('dialog').open)$('dialog').close();const bio=prefsGet('bio')==='1'&&bioReady(),d=document.createElement('div');d.id='lock';d.innerHTML='<div class="lock-box"><span class="logo">'+document.querySelector('.logo').innerHTML+'</span><h2>Mi Quincena</h2><p class="muted">'+(bio?'Tocá el sensor o ingresá tu PIN':'Ingresá tu PIN')+'</p><div class="pin-box"></div><small class="muted">¿Olvidaste el PIN? Solo se recupera borrando los datos de la app desde Ajustes de Android (perdés lo que no tenga copia).</small></div>';document.body.appendChild(d);lockUI=pinUI(d.querySelector('.pin-box'),unlock,{bio});if(bio&&!pinWait())setTimeout(()=>{try{Android.bioAuth()}catch(e){}},300)}
function pinVerify(title,done){modal('<h2>'+esc(title)+'</h2><p class="muted">Ingresá tu PIN actual.</p><div class="pin-box"></div>');pinUI($('modal').querySelector('.pin-box'),()=>{closeModal();done()})}
document.addEventListener('visibilitychange',()=>{if(document.hidden)hiddenAt=Date.now();else if(hiddenAt&&Date.now()-hiddenAt>60000)lockScreen()});

