function excelDate(v){if(v instanceof Date)return [v.getFullYear(),String(v.getMonth()+1).padStart(2,'0'),String(v.getDate()).padStart(2,'0')].join('-');if(typeof v==='number'){const p=XLSX.SSF.parse_date_code(v);return p?`${p.y}-${String(p.m).padStart(2,'0')}-${String(p.d).padStart(2,'0')}`:''}const s=String(v||'').trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))return s.slice(6)+'-'+s.slice(3,5)+'-'+s.slice(0,2);return s;}
function excelTime(v){if(v==null||v==='')return '';if(v instanceof Date)return String(v.getHours()).padStart(2,'0')+':'+String(v.getMinutes()).padStart(2,'0');if(typeof v==='number'){const m=Math.round((v%1)*1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')}const s=String(v).trim();const m=s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);return m?m[1].padStart(2,'0')+':'+m[2]:s;}
